-- Deadline decisions use the clock after acquiring authoritative locks.
-- finalized_at remains the effective submission/cutoff time, clamped on expiry.
create or replace function private.require_access(s uuid,write_new boolean default false) returns void language plpgsql security definer set search_path='' as $$begin if private.school() is distinct from s or private.role() is null then raise exception 'FORBIDDEN' using errcode='42501';end if;if write_new and not exists(select 1 from public.subscriptions where school_id=s and clock_timestamp()>=starts_at and clock_timestamp()<ends_at) then raise exception 'SUBSCRIPTION_EXPIRED';end if;end$$;

create or replace function private.active_attempt() returns boolean language sql volatile security definer set search_path='' as $$select exists(select 1 from public.attempts where student_id=auth.uid() and status='in_progress' and deadline>clock_timestamp())$$;

create or replace function public.start_attempt(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare e public.exam_versions;r public.exam_recipients;a public.attempts;ord jsonb;n timestamptz;begin perform 1 from public.memberships where id=auth.uid()for update;select * into e from public.exam_versions where id=(p->>'versionId')::uuid for update;perform private.require_access(e.school_id);if private.role()<>'student' then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into r from public.exam_recipients where version_id=e.id and student_id=auth.uid();if not found then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into a from public.attempts where version_id=e.id and student_id=auth.uid();n:=clock_timestamp();if found then if a.status='in_progress'and n>=a.deadline then a:=private.finalize(a.id);end if;if a.status='in_progress'and a.writer is distinct from (p->>'writer')::uuid then raise exception 'WRITER_CONFLICT';end if;return case when a.status='in_progress' then to_jsonb(a) else to_jsonb(a)-'writer' end;end if;perform private.require_access(e.school_id,true);if r.exempt or e.status<>'published' or n<e.opens_at or n>=r.closes_at or (e.last_start_at is not null and n>e.last_start_at) or private.active_attempt() then raise exception 'ATTEMPT_UNAVAILABLE';end if;
select jsonb_agg(jsonb_build_object('id',q.id,'options',(select jsonb_agg(o->'id' order by case when e.shuffle and coalesce((q.content->>'shuffleOptions')::boolean,false) then md5(auth.uid()::text||e.id||(o->>'id')) else ordinality::text end) from jsonb_array_elements(q.content->'options')with ordinality as options(o,ordinality))) order by q.content->>'section',case when e.shuffle then md5(auth.uid()::text||e.id||q.id) else lpad(q.position::text,5,'0') end) into ord from public.exam_questions q where q.version_id=e.id;
insert into public.attempts(school_id,version_id,student_id,started_at,deadline,writer,display_order) values(e.school_id,e.id,auth.uid(),n,least(n+make_interval(secs=>e.duration_seconds+r.extra_seconds),r.closes_at),(p->>'writer')::uuid,ord) returning * into a;return to_jsonb(a);end$$;
create or replace function private.finalize(aid uuid,forced boolean default false) returns public.attempts language plpgsql security definer set search_path='' as $$declare a public.attempts;q record;v int;n timestamptz;begin select * into a from public.attempts where id=aid for update;if not found then raise exception 'ATTEMPT_UNAVAILABLE';end if;n:=clock_timestamp();if a.status<>'in_progress' then return a;end if;if not forced and n<a.deadline then raise exception 'NOT_EXPIRED';end if;update public.attempts set status=case when n>=deadline then 'expired' else 'submitted' end,finalized_at=least(n,deadline),receipt=gen_random_uuid() where id=aid returning * into a;for q in select eq.*,k.key,ans.response from public.exam_questions eq join private.question_keys k on k.version_id=eq.version_id and k.question_id=eq.id left join public.answers ans on ans.attempt_id=aid and ans.question_id=eq.id where eq.version_id=a.version_id loop v:=private.objective_score(q.content,q.key,q.response);insert into private.grades(school_id,attempt_id,question_id,objective_score,final_score)values(a.school_id,aid,q.id,v,v)on conflict do nothing;if q.type='subjective' then insert into public.outbox(school_id,kind,dedup_key,payload)values(a.school_id,'subjective',aid||':'||q.id,jsonb_build_object('attemptId',aid,'questionId',q.id,'gradingVersion',1))on conflict do nothing;end if;end loop;return a;end$$;
create or replace function public.save_answer(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;old public.answers;n timestamptz;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid for update;n:=clock_timestamp();perform private.require_access(a.school_id);if a.id is null or a.student_id<>auth.uid() or private.role()<>'student' then raise exception 'FORBIDDEN' using errcode='42501';end if;if n>=a.deadline and a.status='in_progress' then a:=private.finalize(a.id);return jsonb_build_object('error','ATTEMPT_EXPIRED','receipt',a.receipt);end if;if a.status<>'in_progress' then return jsonb_build_object('error','ATTEMPT_FINALIZED');end if;if a.writer is distinct from (p->>'writer')::uuid then return jsonb_build_object('error','WRITER_CONFLICT');end if;if not exists(select 1 from public.exam_questions where version_id=a.version_id and id=(p->>'questionId')::uuid) then raise exception 'INVALID_QUESTION';end if;select * into old from public.answers where attempt_id=a.id and question_id=(p->>'questionId')::uuid;if found and old.revision=(p->>'revision')::int and old.response=p->'response' then return to_jsonb(old);end if;if (p->>'revision')::int<>coalesce(old.revision,0)+1 then return jsonb_build_object('error','STALE_REVISION','currentRevision',old.revision);end if;perform private.validate_response((select content from public.exam_questions where version_id=a.version_id and id=(p->>'questionId')::uuid),p->'response');insert into public.answers values(a.school_id,a.id,(p->>'questionId')::uuid,p->'response',(p->>'revision')::int,n)on conflict(attempt_id,question_id)do update set response=excluded.response,revision=excluded.revision,saved_at=excluded.saved_at returning * into old;return to_jsonb(old);end$$;
create or replace function public.submit_attempt(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid for update;perform private.require_access(a.school_id);if a.id is null or a.student_id<>auth.uid() or private.role()<>'student' then raise exception 'FORBIDDEN' using errcode='42501';end if;if a.status='in_progress' and a.writer is distinct from (p->>'writer')::uuid then raise exception 'WRITER_CONFLICT';end if;return to_jsonb(private.finalize(a.id,true))-'writer';end$$;

create or replace function public.review_details(p jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;begin select * into a from public.attempts where id=(p->>'attemptId')::uuid;if not private.exam_teacher(a.version_id) then raise exception 'FORBIDDEN' using errcode='42501';end if;return jsonb_build_object('attempt',to_jsonb(a)-'writer','grades',(select jsonb_agg(to_jsonb(g))from private.grades g where attempt_id=a.id),'keys',(select jsonb_agg(to_jsonb(k))from private.question_keys k where version_id=a.version_id));end$$;

create or replace function public.runtime_takeover(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare a public.attempts;se private.sessions;m public.memberships;begin select * into se from private.sessions where token_hash=p->>'sessionHash'and revoked_at is null and expires_at>clock_timestamp()and reauthenticated_at>clock_timestamp()-interval '5 minutes';if not found then raise exception 'RECENT_REAUTH_REQUIRED'using errcode='42501';end if;select * into m from public.memberships where id=se.user_id and active and role='student';select * into a from public.attempts where id=(p->>'attemptId')::uuid and student_id=m.id for update;if not found or a.status<>'in_progress'or a.deadline<=clock_timestamp()or exists(select 1 from public.schools where id=a.school_id and status='suspended')then raise exception 'ATTEMPT_UNAVAILABLE';end if;update public.attempts set writer=(p->>'writer')::uuid,writer_epoch=writer_epoch+1 where id=a.id returning * into a;insert into public.audit_events(school_id,actor_id,actor_role,subject_id,action)values(a.school_id,m.id,'student',m.id,'attempt.writer.takeover');return to_jsonb(a);end$$;

-- Row visibility is not permission to read a device's writer token.
revoke select on public.attempts from authenticated;
grant select(id,school_id,version_id,student_id,started_at,deadline,finalized_at,status,writer_epoch,display_order,receipt)on public.attempts to authenticated;
-- Paper metadata remains visible to recipients; question content requires admission.
drop policy read_scope on public.exam_questions;
create policy read_scope on public.exam_questions for select to authenticated using(
 private.exam_teacher(version_id)or(private.role()='student'and exists(
 select 1 from public.attempts a where a.version_id=exam_questions.version_id and a.student_id=auth.uid()and a.school_id=private.school()and a.started_at<=clock_timestamp())));
